import 'dart:async';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:practise_platform_channel_flutter/battery_state.dart';
import 'package:practise_platform_channel_flutter/pigeon/battery_api.g.dart';

class BatteryScreen extends StatefulWidget {
  const BatteryScreen({super.key});

  @override
  State<BatteryScreen> createState() => _BatteryScreenState();
}

class _BatteryScreenState extends State<BatteryScreen> {
  // Generated by Pigeon (replaces MethodChannel + 'getBatteryLevel' string)
  final _batteryHostApi = BatteryHostApi();
  // int? _batteryLevel;
  // bool _isLoading = true;
  // String? _errorMessage;

  //Create single state variable default Loading
  BatteryState _state = BatteryLoading();

  // Keeps the stream subscription so it can be cancelled in dispose
  StreamSubscription<BatteryInfo>? _subscription;

  @override
  void initState() {
    super.initState();
    // Start live updates as soon as screen mounts (triggers onListen in Kotlin)
    _listenToBattery();
  }

  @override
  void dispose() {
    // Stop live updates (triggers onCancel in Kotlin)
    _subscription?.cancel();
    super.dispose();
  }

  void _listenToBattery() {
    // Generated by Pigeon: already a typed Stream<BatteryInfo> (no fromMap)
    _subscription = batteryUpdates().listen(
      (info) {
        setState(() {
          _state = BatterySuccess(info);
        });
      },
      onError: (Object error) {
        // sink.error() in Kotlin arrives here as PlatformException
        setState(() {
          _state = BatteryError(
            error is PlatformException
                ? error.message ?? "Error while listening to battery"
                : error.toString(),
          );
        });
      },
    );
  }

  Future<void> _fetchBatteryLevel() async {
    try {
      final int result = await _batteryHostApi.getBatteryLevel();
      // Screen may have closed while waiting for Kotlin
      if (!mounted) return;
      // setState(() {
      //   _batteryLevel = result;
      //   _isLoading = false;
      // });
      setState(() {
        _state = BatterySuccess(BatteryInfo(level: result));
      });
    } on PlatformException catch (e) {
      if (!mounted) return;
      // setState(() {
      //   _isLoading = false;
      //   _errorMessage = e.message;
      // });
      setState(() {
        _state = BatteryError(
          e.message ?? "Error while fetching battery level",
        );
      });
    }
  }

  String _chargingText(bool? isCharging) => switch (isCharging) {
    true => '⚡ Charging',
    false => '🔋 Not charging',
    null => 'Charging status unknown (one-time read)',
  };

  @override
  Widget build(BuildContext context) {
    final textTheme = Theme.of(context).textTheme;

    return Scaffold(
      appBar: AppBar(title: const Text('Device Status')),
      body: Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            switch (_state) {
              BatteryLoading() => const CircularProgressIndicator(),
              BatteryError(message: final message) => Text(
                message,
                style: textTheme.bodyLarge?.copyWith(
                  color: Theme.of(context).colorScheme.error,
                ),
              ),
              BatterySuccess(info: final info) => Column(
                children: [
                  Text(
                    'Battery level: ${info.level}%',
                    style: textTheme.headlineSmall,
                  ),
                  const SizedBox(height: 8),
                  Text(
                    _chargingText(info.isCharging),
                    style: textTheme.bodyLarge,
                  ),
                ],
              ),
            },
            const SizedBox(height: 24),
            // One-time read through the MethodChannel, for comparison
            OutlinedButton(
              onPressed: _fetchBatteryLevel,
              child: const Text('Refresh once (MethodChannel)'),
            ),
          ],
        ),
      ),
    );
  }
}
